css:
.esgfund-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #d7e2ec;
    background: radial-gradient(1200px 600px at 20% -10%, #11324a 0%, #0a1f2e 45%, #06141d 100%);
    border-radius: 18px;
}

.esgfund-container * {
    box-sizing: border-box;
}

.esgfund-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #0c2c40 0%, #0f4135 55%, #135a3f 100%);
    color: #eafaf3;
    border-radius: 16px;
    margin-bottom: 18px;
    border: 1px solid rgba(46, 196, 138, 0.22);
    box-shadow: 0 14px 40px rgba(0, 0, 0, 0.45);
}

.esgfund-header h1 {
    margin: 10px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.esgfund-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #7ff0c1;
    background: rgba(46, 196, 138, 0.12);
    border: 1px solid rgba(46, 196, 138, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.esgfund-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.55;
    color: #b9d7ce;
}

.esgfund-mandate {
    display: flex;
    align-items: stretch;
    gap: 12px;
    margin-bottom: 18px;
}

.esgfund-mandate-item {
    flex: 1;
    background: #0d2535;
    border: 1px solid rgba(120, 160, 190, 0.16);
    border-radius: 14px;
    padding: 14px 18px;
    display: flex;
    flex-direction: column;
    gap: 5px;
}

.esgfund-mandate-cov { border-left: 5px solid #2ec48a; }
.esgfund-mandate-budget { border-left: 5px solid #4d9fe0; }

.esgfund-mandate-name {
    font-weight: 800;
    font-size: 1.02rem;
    color: #eaf2f8;
    text-transform: uppercase;
    letter-spacing: 0.6px;
}

.esgfund-mandate-cov .esgfund-mandate-name { color: #5fe3ad; }
.esgfund-mandate-budget .esgfund-mandate-name { color: #6fb6ec; }

.esgfund-mandate-meta {
    font-size: 0.82rem;
    color: #93a9b9;
    line-height: 1.42;
}

.esgfund-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #a7bccb;
    margin-bottom: 16px;
    padding: 4px 4px;
}

.esgfund-period-counter #currentDay,
.esgfund-period-counter #maxPeriods {
    font-weight: 800;
    color: #2ec48a;
}

.esgfund-round-name {
    background: rgba(46, 196, 138, 0.16);
    color: #5fe3ad;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.esgfund-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #f0b34d;
    background: rgba(240, 179, 77, 0.12);
    border: 1px solid rgba(240, 179, 77, 0.34);
    padding: 4px 12px;
    border-radius: 999px;
}

.esgfund-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.esgfund-status-card {
    background: linear-gradient(180deg, #0e2839 0%, #0b2030 100%);
    border: 1px solid rgba(120, 160, 190, 0.14);
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.35);
    border-top: 4px solid #2ec48a;
}

.esgfund-card-esg { border-top-color: #2ec48a; }
.esgfund-card-vol { border-top-color: #4d9fe0; }
.esgfund-card-dd { border-top-color: #f0b34d; }
.esgfund-card-ret { border-top-color: #c98bdc; }

.esgfund-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8aa0b0;
}

.esgfund-value {
    font-size: 2.6rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #eaf2f8;
    font-variant-numeric: tabular-nums;
}

.esgfund-card-esg .esgfund-value { color: #2ec48a; }
.esgfund-card-vol .esgfund-value { color: #4d9fe0; }
.esgfund-card-dd .esgfund-value { color: #f0b34d; }
.esgfund-card-ret .esgfund-value { color: #c98bdc; }

.esgfund-sublabel {
    font-size: 0.75rem;
    color: #7e94a4;
    line-height: 1.35;
}

/* Danger / safe state recolouring driven by the adapter. */
.esgfund-card-esg.esgfund-breach { border-top-color: #ef5d5d; }
.esgfund-card-esg.esgfund-breach .esgfund-value { color: #ef5d5d; }
.esgfund-card-esg.esgfund-safe { border-top-color: #2ec48a; }
.esgfund-card-esg.esgfund-safe .esgfund-value { color: #2ec48a; }

.esgfund-card-vol.esgfund-breach { border-top-color: #ef5d5d; }
.esgfund-card-vol.esgfund-breach .esgfund-value { color: #ef5d5d; }
.esgfund-card-vol.esgfund-safe .esgfund-value { color: #4d9fe0; }

.esgfund-card-dd.esgfund-breach { border-top-color: #ef5d5d; }
.esgfund-card-dd.esgfund-breach .esgfund-value { color: #ef5d5d; }
.esgfund-card-dd.esgfund-warn .esgfund-value { color: #f0b34d; }

.esgfund-card-ret.esgfund-good .esgfund-value { color: #2ec48a; }

.esgfund-alert-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #0d2535;
    border: 1px solid rgba(239, 93, 93, 0.30);
    color: #a7bccb;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.esgfund-alert-bar #alertDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #ef5d5d;
    font-weight: 800;
}

.esgfund-alert-bar.esgfund-alert-ok { border-color: rgba(46, 196, 138, 0.40); }
.esgfund-alert-bar.esgfund-alert-ok #alertDisplay { color: #2ec48a; }
.esgfund-alert-bar.esgfund-alert-warn { border-color: rgba(240, 179, 77, 0.40); }
.esgfund-alert-bar.esgfund-alert-warn #alertDisplay { color: #f0b34d; }

.esgfund-briefing {
    display: flex;
    gap: 14px;
    background: #0d2535;
    border-left: 5px solid #2ec48a;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.30);
}

.esgfund-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.esgfund-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #eaf2f8;
    margin-bottom: 6px;
}

.esgfund-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #b9cdda;
}

.esgfund-briefing-text strong { color: #5fe3ad; }
.esgfund-briefing-text em { color: #f0b34d; font-style: italic; }

.esgfund-controls {
    background: #0d2535;
    border: 1px solid rgba(120, 160, 190, 0.12);
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.30);
}

.esgfund-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #eaf2f8;
    border-bottom: 2px solid rgba(120, 160, 190, 0.18);
    padding-bottom: 8px;
}

.esgfund-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #cdddE8;
    margin: 14px 0 6px;
}

.esgfund-shock {
    background: rgba(239, 93, 93, 0.12);
    border: 1px solid rgba(239, 93, 93, 0.45);
    border-left: 5px solid #ef5d5d;
    border-radius: 10px;
    padding: 12px 14px;
    margin-bottom: 6px;
    font-size: 0.88rem;
    font-weight: 700;
    line-height: 1.45;
    color: #ffb9b9;
}

.esgfund-container select,
.esgfund-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #2a4b5f;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #0a1c29;
    color: #e7f1f7;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.esgfund-container select:focus,
.esgfund-container input[type="number"]:focus {
    outline: none;
    border-color: #2ec48a;
    box-shadow: 0 0 0 3px rgba(46, 196, 138, 0.20);
}

.esgfund-container select option {
    background-color: #0a1c29;
    color: #e7f1f7;
}

.esgfund-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #2ec48a;
}

.esgfund-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #a7bccb;
    margin-top: 4px;
}

.esgfund-range-readout span:nth-child(2) {
    color: #2ec48a;
    font-weight: 800;
}

.esgfund-hint {
    font-size: 0.8rem;
    color: #7e94a4;
    margin-top: 6px;
    line-height: 1.4;
    font-style: italic;
}

.esgfund-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.esgfund-container .btn-primary {
    background: linear-gradient(135deg, #15795a 0%, #2ec48a 100%);
    border: none;
    color: #04221a;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 20px rgba(46, 196, 138, 0.30);
}

.esgfund-container .btn-primary:hover {
    filter: brightness(1.08);
}

.esgfund-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #2a4b5f;
    color: #a7bccb;
    background: transparent;
}

.esgfund-coach {
    background: linear-gradient(160deg, #0c2c40 0%, #0a2233 100%);
    border: 1px solid rgba(46, 196, 138, 0.18);
    color: #cfe6df;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 22px rgba(0, 0, 0, 0.34);
}

.esgfund-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f0b34d;
    margin-bottom: 8px;
}

.esgfund-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.esgfund-coach-body strong { color: #7ff0c1; }
.esgfund-coach-body em { color: #f0b34d; font-style: italic; }

.esgfund-history,
.esgfund-chart {
    background: #0d2535;
    border: 1px solid rgba(120, 160, 190, 0.12);
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.30);
}

.esgfund-history h3,
.esgfund-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #eaf2f8;
}

.esgfund-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #c2d4df;
}

.esgfund-container table#usfHistoryTable th {
    background: #0a1c29;
    color: #5fe3ad;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #1f3d4f;
}

.esgfund-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #16303f;
    color: #c2d4df;
}

.esgfund-container table#usfHistoryTable tr:nth-child(even) td {
    background: #0b2030;
}

.esgfund-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .esgfund-container {
        padding: 14px;
    }
    .esgfund-header h1 {
        font-size: 1.7rem;
    }
    .esgfund-mandate {
        flex-direction: column;
    }
    .esgfund-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .esgfund-value {
        font-size: 2rem;
    }
    .esgfund-clock {
        margin-left: 0;
    }
    .esgfund-period-counter {
        font-size: 0.88rem;
    }
    .esgfund-alert-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .esgfund-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 FIX B - completion / LP-board debrief scorecard (append-only, namespaced) ===== */
.esg-cm { padding: 12px 6px; text-align: center; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif; }
.esg-cm-heading { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: #7a8398; margin-bottom: 6px; }
.esg-cm-verdict { font-size: 22px; font-weight: 700; color: #eceff6; margin-bottom: 8px; }
.esg-cm-score { font-size: 16px; color: #eceff6; margin-bottom: 16px; }
.esg-cm-score strong { color: #4f9bd9; }
.esg-cm-sub { font-size: 11px; letter-spacing: .06em; text-transform: uppercase; color: #7a8398; margin-bottom: 8px; }
.esg-cm-targets { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; margin-bottom: 16px; }
.esg-cm-target { display: inline-flex; align-items: center; gap: 6px; padding: 6px 11px; border-radius: 20px; font-size: 13px; border: 1px solid transparent; }
.esg-cm-target.esg-cm-met { background: rgba(79,155,217,0.16); color: #8fc3ea; border-color: rgba(79,155,217,0.4); }
.esg-cm-target.esg-cm-missed { background: rgba(255,110,110,0.14); color: #ff9d9d; border-color: rgba(255,110,110,0.36); }
.esg-cm-tick { font-weight: 700; }
.esg-cm-metrics { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin-bottom: 16px; }
.esg-cm-metric { display: inline-flex; flex-direction: column; align-items: center; gap: 2px; padding: 9px 13px; background: rgba(120,135,175,0.12); border-radius: 8px; min-width: 92px; }
.esg-cm-metric span { font-size: 11px; letter-spacing: .03em; text-transform: uppercase; color: #7a8398; }
.esg-cm-metric strong { font-size: 16px; color: #eceff6; }
.esg-cm-insights { list-style: none; padding: 0; margin: 0 auto; max-width: 720px; text-align: left; }
.esg-cm-insights li { padding: 9px 13px; margin-bottom: 7px; background: rgba(79,155,217,0.10); border-left: 3px solid #4f9bd9; border-radius: 4px; color: #dde5f1; font-size: 13px; line-height: 1.45; }
@media (max-width: 640px) { .esg-cm-metric { min-width: 70px; } .esg-cm-verdict { font-size: 19px; } }

