        _composite(ds) {
            // v1.1.0 - verbatim v1.0.0 composite formula incl. both gate caps.
            const esg = Math.round(ds.esg);
            const vol = Math.round(ds.vol * 10) / 10;
            const dd = Math.round(ds.dd * 10) / 10;
            const gap = Math.round(ds.gap);
            const esgScore = Math.max(0, Math.min(100, (esg - this.ESG_FLOOR + 10) * 5));
            const volScore = Math.max(0, Math.min(100, 100 - (vol - this.VOL_CEIL) * 12));
            const ddScore = Math.max(0, Math.min(100, 100 - (dd - 8) * 11));
            const gapScore = Math.max(0, Math.min(100, 100 + gap / 6));
            let composite = Math.round(esgScore * 0.34 + volScore * 0.24 + ddScore * 0.20 + gapScore * 0.22);
            if (ds.redemptionArmed) composite = Math.min(composite, 35);
            if (ds.forcedStop) composite = Math.min(composite, 30);
            return composite;
        }

        formatCompletionMessage(summary) {
            // v1.1.0 FIX B - localized LP-board debrief scorecard (was: framework default that discarded
            // score, tier, targets and insights).
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t.bind(window.mySimulation)
                : function (k) { return k; };
            summary = summary || {};
            const score = (summary.composite != null) ? summary.composite : (summary.score != null ? summary.score : 0);
            const verdict = summary.gradeKey ? t(summary.gradeKey) : (summary.performance || '');
            const insights = summary.insights || [];
            const chip = function (ok, label) {
                return '<div class="esg-cm-target ' + (ok ? 'esg-cm-met' : 'esg-cm-missed') + '">'
                    + '<span class="esg-cm-tick">' + (ok ? '✓' : '✗') + '</span><span>' + label + '</span></div>';
            };
            const targets = ''
                + chip(!!summary.covenantHeld, t('tgt_covenant'))
                + chip(!!summary.volOk, t('tgt_vol'))
                + chip(!!summary.ddOk, t('tgt_dd'))
                + chip(!!summary.buffered, t('tgt_buffer'))
                + chip(!!summary.thresholdHeld, t('tgt_threshold'));
            const metric = function (label, val) {
                return '<div class="esg-cm-metric"><span>' + label + '</span><strong>' + val + '</strong></div>';
            };
            const nz = function (v) { return (v != null) ? v : '-'; };
            const metrics = ''
                + metric(t('kpi_esg'), nz(summary.esg))
                + metric(t('kpi_vol'), nz(summary.vol) + '%')
                + metric(t('kpi_dd'), nz(summary.dd) + '%')
                + metric(t('kpi_gap'), nz(summary.gap) + ' bps');
            const items = insights.map(function (s) { return '<li>' + s + '</li>'; }).join('');
            return ''
                + '<div class="esg-cm">'
                +   '<div class="esg-cm-heading">' + t('comp_heading') + '</div>'
                +   '<div class="esg-cm-verdict">' + verdict + '</div>'
                +   '<div class="esg-cm-score">' + t('comp_score_label') + ': <strong>' + score + '</strong> / 100</div>'
                +   '<div class="esg-cm-sub">' + t('comp_targets_heading') + '</div>'
                +   '<div class="esg-cm-targets">' + targets + '</div>'
                +   '<div class="esg-cm-metrics">' + metrics + '</div>'
                +   (items ? '<ul class="esg-cm-insights">' + items + '</ul>' : '')
                + '</div>';
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t.bind(window.mySimulation) : function (k) { return k; };
            const ds = window.mySimulation.state.domainState;
            const esg = Math.round(ds.esg);
            const vol = Math.round(ds.vol * 10) / 10;
            const dd = Math.round(ds.dd * 10) / 10;
            const gap = Math.round(ds.gap);
            const buffer = Math.round(ds.buffer * 10) / 10;

            const covenantHeld = esg >= this.ESG_FLOOR && !ds.redemptionArmed;
            const volOk = vol <= this.VOL_CEIL;
            const ddOk = dd < this.DD_STOP && !ds.forcedStop;
            const returnOk = gap >= -120;
            const buffered = buffer >= 3;
            // Defending the mandate requires keeping a genuine ESG threshold. Dropping the
            // dial to ≥CCC/≥BB abandons the integrity mandate the LPs bought ("you are no
            // longer the ESG Leaders Fund") — so it bars the top verdict even if the
            // weighted score was later rebuilt with high-rated names.
            const thresholdHeld = !ds.thresholdLoosened;

            // Composite: covenant integrity carries the most weight, then the risk
            // budget (vol+dd), then return recovery.
            const esgScore = Math.max(0, Math.min(100, (esg - this.ESG_FLOOR + 10) * 5));   // floor=50, +10 over=100
            const volScore = Math.max(0, Math.min(100, 100 - (vol - this.VOL_CEIL) * 12));
            const ddScore = Math.max(0, Math.min(100, 100 - (dd - 8) * 11));
            const gapScore = Math.max(0, Math.min(100, 100 + gap / 6));                     // gap 0 -> 100, -600 -> 0
            // v1.1.0 FIX A - composite (incl. both gate caps) delegated to _composite(ds) so the persisted
            // per-round score and this completion composite are identical by construction (formula unchanged).
            // The esgScore/volScore/ddScore/gapScore locals above are left in place (now unused, harmless).
            const composite = this._composite(ds);

            let pattern = `mixed`;
            if (ds.forcedStop) pattern = `forcedstop`;
            else if (ds.redemptionArmed || (!covenantHeld && ds.returnChased)) pattern = `returnchase`;
            else if (ds.overProtected && !volOk) pattern = `overprotect`;
            else if (covenantHeld && volOk && ddOk && buffered && thresholdHeld) pattern = `balanced`;

            // v1.1.0 FIX C - tier resolved to an i18n key and localized via t() (was hardcoded English).
            let perfKey = `grade_lost`;
            if (covenantHeld && volOk && ddOk && buffered && thresholdHeld && composite >= 75) perfKey = `grade_defended`;
            else if (covenantHeld && volOk && ddOk) perfKey = `grade_inside`;
            else if (ds.redemptionArmed) perfKey = `grade_redemption`;
            else if (ds.forcedStop) perfKey = `grade_forced`;
            else if (composite >= 55) perfKey = `grade_partial`;
            const performance = t(perfKey);

            const insights = [];
            if (pattern === `balanced` && composite >= 75) insights.push(window.mySimulation.t(`insight_balanced`));
            else if (pattern === `returnchase`) insights.push(window.mySimulation.t(`insight_returnchase`));
            else if (pattern === `overprotect`) insights.push(window.mySimulation.t(`insight_overprotect`));
            else if (pattern === `forcedstop`) insights.push(window.mySimulation.t(`insight_forcedstop`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (ds.redemptionArmed) insights.push(window.mySimulation.t(`insight_redemption`));
            if (!buffered && covenantHeld) insights.push(window.mySimulation.t(`insight_nobuffer`));
            if (!volOk) insights.push(window.mySimulation.t(`insight_vol`));
            if (ds.impactCost > 0) insights.push(window.mySimulation.t(`insight_impact`));
            if (covenantHeld && volOk && ddOk && gap < -200) insights.push(window.mySimulation.t(`insight_returncost`));

            return {
                gradeKey: perfKey,
                score: composite,
                thresholdHeld: thresholdHeld,
                esg: esg,
                vol: vol,
                dd: dd,
                gap: gap,
                buffer: buffer,
                impactCost: ds.impactCost,
                covenantHeld: covenantHeld,
                volOk: volOk,
                ddOk: ddOk,
                returnOk: returnOk,
                buffered: buffered,
                redemptionArmed: ds.redemptionArmed,
                forcedStop: ds.forcedStop,
                pattern: pattern,
                composite: composite,
                performance: performance,
                insights: insights
            };
        }

